const PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>', '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

class ScanError extends Error {
  constructor(line, col, reason) { super(reason); this.line = line; this.col = col }
}

const isDec = (c) => c !== undefined && c >= '0' && c <= '9'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'
const isAlpha = (c) => c !== undefined && /^[A-Za-z_]$/.test(c)
const isIdent = (c) => isAlpha(c) || isDec(c)

function scan(text) {
  const s = Array.from(text)
  const n = s.length
  const toks = []
  let i = 0, line = 1, col = 1
  const adv = () => {
    const c = s[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  const err = (l, c, m) => { throw new ScanError(l, c, m) }

  while (i < n) {
    const c = s[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && s[i + 1] === '/') {
      while (i < n && s[i] !== '\n') adv()
      continue
    }
    if (c === '/' && s[i + 1] === '*') {
      const l0 = line, c0 = col
      adv(); adv()
      let depth = 1
      while (depth > 0) {
        if (i >= n) err(l0, c0, 'unterminated block comment')
        if (s[i] === '/' && s[i + 1] === '*') { adv(); adv(); depth++ }
        else if (s[i] === '*' && s[i + 1] === '/') { adv(); adv(); depth-- }
        else adv()
      }
      continue
    }
    const l0 = line, c0 = col
    if (c === 'r' && s[i + 1] === '"') {
      adv(); adv()
      let v = ''
      for (;;) {
        if (i >= n) err(l0, c0, 'unterminated string')
        const ch = adv()
        if (ch === '"') break
        v += ch
      }
      toks.push({ line: l0, col: c0, kind: 'rawstring', body: JSON.stringify(v) })
      continue
    }
    if (isAlpha(c)) {
      let t = ''
      while (i < n && isIdent(s[i])) t += adv()
      toks.push({ line: l0, col: c0, kind: KEYWORDS.has(t) ? 'keyword' : 'ident', body: t })
      continue
    }
    if (isDec(c)) {
      let t = ''
      let bad = false
      const run = (pred) => {
        // a run of digits with single underscores between digits
        if (!pred(s[i])) return false
        t += adv()
        for (;;) {
          if (pred(s[i])) t += adv()
          else if (s[i] === '_' && pred(s[i + 1])) { t += adv(); t += adv() }
          else break
        }
        return true
      }
      const p = s[i + 1]
      const radix = c === '0' ? { x: isHex, X: isHex, b: isBin, B: isBin, o: isOct, O: isOct }[p] : undefined
      if (radix) {
        t += adv(); t += adv()
        if (!run(radix)) bad = true
      } else {
        run(isDec)
        if (s[i] === '.' && isDec(s[i + 1])) { t += adv(); run(isDec) }
        if (s[i] === 'e' || s[i] === 'E') {
          const a = s[i + 1], b = s[i + 2]
          if (isDec(a)) { t += adv(); run(isDec) }
          else if ((a === '+' || a === '-') && isDec(b)) { t += adv(); t += adv(); run(isDec) }
        }
      }
      if (i < n && isIdent(s[i])) {
        bad = true
        while (i < n && isIdent(s[i])) t += adv()
      }
      if (bad) err(l0, c0, 'invalid number ' + t)
      toks.push({ line: l0, col: c0, kind: 'number', body: t })
      continue
    }
    if (c === '"') {
      adv()
      let v = ''
      for (;;) {
        if (i >= n) err(l0, c0, 'unterminated string')
        const lc = line, cc = col
        const ch = s[i]
        if (ch === '\n') err(lc, cc, 'newline in string')
        adv()
        if (ch === '"') break
        if (ch !== '\\') { v += ch; continue }
        if (i >= n) err(l0, c0, 'unterminated string')
        const e = s[i]
        const bad = () => err(lc, cc, 'invalid escape \\' + e)
        if (e === 'n') { adv(); v += '\n' }
        else if (e === 't') { adv(); v += '\t' }
        else if (e === 'r') { adv(); v += '\r' }
        else if (e === '\\') { adv(); v += '\\' }
        else if (e === '"') { adv(); v += '"' }
        else if (e === '0') { adv(); v += '\0' }
        else if (e === 'x') {
          if (!isHex(s[i + 1]) || !isHex(s[i + 2])) bad()
          adv()
          v += String.fromCharCode(parseInt(adv() + adv(), 16))
        } else if (e === 'u') {
          if (s[i + 1] !== '{') bad()
          let j = i + 2, h = ''
          while (isHex(s[j])) h += s[j++]
          if (!h || s[j] !== '}') bad()
          const stripped = h.replace(/^0+/, '')
          if (stripped.length > 6 || (stripped && parseInt(stripped, 16) > 0x10ffff)) bad()
          while (i <= j) adv()
          v += String.fromCodePoint(parseInt(h, 16))
        } else bad()
      }
      toks.push({ line: l0, col: c0, kind: 'string', body: JSON.stringify(v) })
      continue
    }
    const two = c + (s[i + 1] ?? '')
    const p = PUNCT.find((x) => (x.length === 2 ? x === two : x === c))
    if (!p) err(l0, c0, 'unexpected character ' + c)
    for (let k = 0; k < p.length; k++) adv()
    toks.push({ line: l0, col: c0, kind: 'punct', body: p })
  }
  return toks
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}
let out = ''
try {
  const toks = scan(readFileSync(0, 'utf8'))
  if (args[0] === 'tokens') {
    for (const t of toks) out += `${t.line}:${t.col} ${t.kind} ${t.body}\n`
  } else {
    for (const k of KINDS) out += `${k} ${toks.filter((t) => t.kind === k).length}\n`
    out += `total ${toks.length}\n`
  }
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.line}:${e.col}: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(out)
